// Hole die organischen Suchergebnisse
const results = $json.organic_results || [];

// Reduziere auf max. 5 Ergebnisse
const topResults = results.slice(0, 5);

// Gebe gefilterte Items zurück
return topResults.map(r => ({
  title: r.title,
  link: r.link,
  snippet: r.snippet
}));

let text = "";

for (const item of $items()) {
  text += `Title: ${item.json.title}\n`;
  text += `Link: ${item.json.link}\n`;
  text += `Summary: ${item.json.snippet}\n`;
  text += `\n---------------------------\n\n`;
}

return [{
  json: {
    combined: text
  }
}];

/**
 * Erwarteter Input:
 * {
 *   response: "{ ... JSON vom LLM ... }"
 * }
 *
 * Output:
 * 1) Wenn Name extrahierbar → { firstName, lastName, hint, keywords, raw, parsedRaw }
 * 2) Wenn Name NICHT extrahierbar → { status: "not_found", data: null, message: "..." }
 */

const out = [];

for (const item of $items()) {
  const src = item.json || {};
  let parsed = {};

  // -----------------------------
  // JSON aus src.response extrahieren
  // -----------------------------
  try {
    const raw = (src.response || "").trim();

    try {
      parsed = JSON.parse(raw);
    } catch (e) {
      // Falls Text um das JSON herum ist
      const match = raw.match(/\{[\s\S]*\}/);
      if (match) {
        parsed = JSON.parse(match[0]);
      } else {
        throw e;
      }
    }
  } catch (err) {
    parsed = {
      firstName: null,
      lastName: null,
      hint: "Fehler beim Parsen",
      keywords: [],
      _parseError: String(err),
    };
  }

  const firstName = parsed.firstName ?? null;
  const lastName  = parsed.lastName ?? null;
  const hint      = parsed.hint ?? null;
  const keywords  = Array.isArray(parsed.keywords) ? parsed.keywords : [];

  // ---------------------------------------------------
  // ❗❗ NOT-FOUND-CHECK:
  // Wenn KEIN Name extrahiert werden konnte → Flow abbrechen
  // ---------------------------------------------------
  if (!firstName && !lastName) {
    out.push({
      json: {
        status: "not_found",
        data: null,
        message: hint || "Es konnte keine Person aus dem Prompt extrahiert werden.",
      },
    });
    continue; // dieses Item nicht weiterverarbeiten
  }

  // ---------------------------------------------------
  // Normaler Output für erfolgreiche Extraktion
  // ---------------------------------------------------
  out.push({
    json: {
      firstName,
      lastName,
      hint,
      keywords,
      raw: src,
      parsedRaw: parsed,
    },
  });
}

return out;

// Input kommt vom PDF-Webhook so rein:
// {
//   headers: {...},
//   params: {...},
//   query: {...},
//   body: {
//     status: "ok",
//     data: { canonicalName, shortBio, facts, confidence },
//     message: "..."
//
//   },
//   ...
// }
//
// -> Wir müssen also aus item.json.body.data lesen, nicht aus item.json.data

const items = $items();
const out = [];

for (const item of items) {
  const root = item.json || {};
  const body = root.body || {};          // <--- WICHTIG
  const data = body.data || {};          // <--- HIER liegen canonicalName, shortBio etc.

  const name = data.canonicalName || '–';
  const shortBio = data.shortBio || '';
  const facts = Array.isArray(data.facts) ? data.facts : [];
  const confidence = typeof data.confidence === 'number'
    ? Math.round(data.confidence * 100)
    : null;

  // shortBio-Zeilenumbrüche in <p> + <br> umwandeln
  const bioHtml = shortBio
    ? shortBio
        .split(/\n{2,}/)
        .map(block => `<p>${block.replace(/\n/g, '<br>')}</p>`)
        .join('\n')
    : '<p>Keine Kurzbiografie vorhanden.</p>';

  const factsHtml = facts.length
    ? facts.map(f => {
        const key = f.key || '';
        const value = f.value || '';
        return `
          <div class="fact">
            <b>${key}</b>
            <div>${value}</div>
          </div>
        `;
      }).join('\n')
    : '<p>Keine zusätzlichen Fakten vorhanden.</p>';

  const confHtml = confidence !== null
    ? `<div class="confidence">Confidence: ${confidence}%</div>`
    : '';

  const html = `
<!doctype html>
<html>
<head>
  <meta charset="utf-8" />
  <title>Steckbrief – ${name}</title>
  <style>
    body { font-family: Arial, sans-serif; padding: 24px; color: #111; }
    h1 { font-size: 24px; margin-bottom: 4px; }
    h2 { margin-top: 24px; margin-bottom: 8px; font-size: 18px; }
    .subtitle { color: #555; margin-bottom: 12px; }
    .confidence { margin-top: 4px; color: #555; font-size: 12px; }
    .fact { margin-bottom: 10px; }
    .fact b { display: block; margin-bottom: 2px; }
    hr { margin: 20px 0; border: none; border-top: 1px solid #ddd; }
  </style>
</head>
<body>
  <h1>${name}</h1>
  <div class="subtitle">Automatisch generierter Steckbrief</div>
  ${confHtml}
  <hr />
  <h2>Kurzprofil</h2>
  ${bioHtml}
  <h2>Fakten & Quellen</h2>
  ${factsHtml}
</body>
</html>
`;

  out.push({
    json: {
      html
    }
  });
}

return out;

/**
 * Eingänge:
 * - $json: enthält mindestens die LLM-Antwort (response oder body.response)
 * - optional: $json.links (wenn du sie vorher schon reingemappt hast)
 * - optional: $json.parsedRaw oder $json.firstName/lastName/hint/keywords
 * - Fallback: $items('Extract Links'), $items('Parser')
 */

/** @type {{ response?: string; body?: any; links?: any; parsedRaw?: any; firstName?: string; lastName?: string; hint?: string; keywords?: string[]; }} */
const res = $json;

// ---------- 1) LLM-Text robust extrahieren ----------
let llmText = null;

if (typeof res?.response === 'string') {
  llmText = res.response;
} else if (Array.isArray(res) && typeof res[0]?.response === 'string') {
  llmText = res[0].response;
} else if (typeof res?.body === 'string') {
  try {
    const b = JSON.parse(res.body);
    if (typeof b?.response === 'string') llmText = b.response;
    else if (Array.isArray(b) && typeof b[0]?.response === 'string') llmText = b[0].response;
  } catch {}
} else if (res?.body && typeof res.body === 'object') {
  const b = res.body;
  if (typeof b?.response === 'string') llmText = b.response;
  else if (Array.isArray(b) && typeof b[0]?.response === 'string') llmText = b[0].response;
}

// ---------- 2) Links holen (erst aus $json, sonst aus "Extract Links") ----------
/** @type {{ title?: string; link?: string; snippet?: string; source?: string; _score?: number; }[]} */
let links = [];

if (Array.isArray(res.links)) {
  links = res.links;
} else {
  // Fallback: nimm die Items aus "Extract Links", falls vorhanden
  try {
    links = $items('Extract Links').map(i => i.json || {});
  } catch {
    links = [];
  }
}

// ---------- 3) Parser-Daten holen (erst aus $json, sonst aus "Parser") ----------
/** @type {{ firstName?: string | null; lastName?: string | null; hint?: string | null; keywords?: string[] | null; }} */
let parsed = {};

if (res.parsedRaw || res.firstName || res.lastName || res.hint || res.keywords) {
  parsed = res.parsedRaw || {
    firstName: res.firstName,
    lastName: res.lastName,
    hint: res.hint,
    keywords: res.keywords,
  };
} else {
  try {
    const pItem = $items('Parser')[0]?.json || {};
    parsed = pItem.parsedRaw || pItem;
  } catch {
    parsed = {};
  }
}

const firstName = (parsed.firstName || '').toLowerCase();
const lastName  = (parsed.lastName  || '').toLowerCase();
const hint      = (parsed.hint      || '').toLowerCase();
const keywords  = Array.isArray(parsed.keywords)
  ? parsed.keywords.map(k => String(k).toLowerCase())
  : [];

// ---------- 4) Namen aus LLM-Text heuristisch ziehen ----------
let canonicalName = '';
if (llmText) {
  const m = llmText.match(/^\s*Personenprofil:\s*([^\n\r]+)/i);
  if (m) canonicalName = m[1].trim();
}

// Fallback: aus erstem Link-Titel Name ableiten
if (!canonicalName && links.length > 0 && links[0].title) {
  let t = String(links[0].title);
  t = t.split(' - ')[0];
  t = t.split('(')[0];
  canonicalName = t.trim();
}

// ---------- 5) Kurz-Bio setzen ----------
const shortBio = llmText?.trim() || null;

// ---------- 6) Faktenliste bauen ----------
/** @type {{ key: string; value: string; source: string; }[]} */
const facts = [];

const add = (k, v, s = 'Web') => {
  if (v !== null && v !== undefined && String(v).trim() !== '') {
    facts.push({ key: k, value: String(v), source: s });
  }
};

// Nur Links als Fakten (keine Snippets mehr)
for (const r of links) {
  const title = r?.title || '';
  const link  = r?.link  || '';
  if (link) add(`Quelle: ${title || 'Link'}`, link, 'Web');
}

// ---------- 7) CONFIDENCE SCORE ----------
function domainScore(url) {
  const u = (url || '').toLowerCase();
  let s = 0;
  if (!u) return 0;

  if (u.includes('wikipedia.org')) s += 0.6;
  if (u.includes('.gov') || u.includes('.gouv')) s += 0.5;
  if (u.includes('handelsregister') || u.includes('unternehmensregister')) s += 0.5;
  if (u.endsWith('.de') && !u.includes('blog') && !u.includes('forum')) s += 0.2;

  return s;
}

function textScore(title, snippet) {
  const t = (title || '').toLowerCase();
  const s = (snippet || '').toLowerCase();
  let score = 0;

  const fullName = `${firstName} ${lastName}`.trim();
  if (fullName && (t.includes(fullName) || s.includes(fullName))) score += 0.5;

  if (firstName && (t.includes(firstName) || s.includes(firstName))) score += 0.15;
  if (lastName  && (t.includes(lastName)  || s.includes(lastName)))  score += 0.15;

  if (hint) {
    const parts = hint.split(/\s+/).filter(w => w.length > 2);
    for (const p of parts) {
      if (t.includes(p) || s.includes(p)) score += 0.05;
    }
  }

  for (const kw of keywords) {
    if (t.includes(kw) || s.includes(kw)) score += 0.1;
  }

  return score;
}

function linkScore(r) {
  const s = domainScore(r.link) + textScore(r.title, r.snippet);
  r._score = s;
  return s;
}

let totalScore = 0;
let bestScore = 0;

for (const r of links) {
  const s = linkScore(r);
  totalScore += s;
  if (s > bestScore) bestScore = s;
}

let confidence = 0.3;

if (links.length > 0) {
  const base = 1 - 1 / (1 + totalScore);
  const boost = Math.min(bestScore / 2, 0.3);
  confidence = base + boost;
} else {
  confidence = 0.2;
}

if (!shortBio) confidence -= 0.15;

if (confidence < 0.1) confidence = 0.1;
if (confidence > 0.98) confidence = 0.98;

// ---------- 8) Ergebnis ----------
return {
  json: {
    status: 'ok',
    data: {
      canonicalName,
      image: null,
      urls: { wikipedia: null },
      shortBio,
      facts,
      confidence
    },
    message: 'Built from web search + LLM'
  }
};
